335|    public function updateHardware(): void
336|    {
337|        $accessibleIds = $this->accessibleUnitIds();
338|
339|        // Issue #842: the destination person must be inside the caller's scope before
340|        // anything is written. The explicit check comes FIRST so a legitimate user who
341|        // types another unit's n_code gets the Persian message instead of a bare
342|        // validation error; the scoped exists rule is the second layer of the same
343|        // contract (same two-layer shape as createHardware()).
344|        if (filled($this->n_code)) {
345|            $person = Person::where('n_code', $this->n_code)->first();
346|
347|            if (! in_array($person?->u_id, $accessibleIds)) {
348|                $this->error('شما به این پرسنل دسترسی ندارید.', position: 'toast-bottom');
349|
350|                return;
351|            }
352|        }
353|
354|        $this->validate([
355|            'n_code' => ['required', 'string', Rule::exists('persons', 'n_code')->where(fn ($q) => $q->whereIn('u_id', $accessibleIds))],
356|            'pc_name' => 'required|string|max:255',
357|        ]);
358|
359|        $hw = Hardware::with('person')->findOrFail($this->editingId);
360|
361|        if (! in_array($hw->person?->u_id, $accessibleIds)) {
362|            $this->error('شما به این سخت‌افزار دسترسی ندارید.', position: 'toast-bottom');
363|
364|            return;
365|        }
366|
367|        $hw->update($this->only([
368|            'n_code', 'pc_name', 'type', 'os', 'ip_valid', 'ip_local', 'mac',
369|            'net_type', 'switch', 'port', 'shutdown', 'vlan', 'motherboard',
370|            'cpu', 'ram', 'hdd', 'comments', 'mark', 'clean_at',
371|        ]));
372|
373|        $this->success("سخت افزار {$this->pc_name} بروزرسانی شد", 'با موفقیت', position: 'toast-bottom');
374|        $this->cancelEdit();
375|    }
