514|    public function hardwares(): LengthAwarePaginator
515|    {
516|        if ($this->hardwaresCache !== null) {
517|            return $this->hardwaresCache;
518|        }
519|
520|        $query = $this->applyOrgScope(Hardware::with('person.unit'));
521|
522|        // General search
523|        if (! empty($this->search)) {
524|            $s = self::foldedTerm($this->search);
525|            $query->where(function ($q) use ($s) {
526|                $q->where('pc_name', 'LIKE', "%{$s}%")
527|                    ->orWhere('n_code', 'LIKE', "%{$s}%")
528|                    ->orWhere('ip_valid', 'LIKE', "%{$s}%")
529|                    ->orWhere('ip_local', 'LIKE', "%{$s}%")
530|                    ->orWhere('mac', 'LIKE', "%{$s}%")
531|                    ->orWhere('comments', 'LIKE', "%{$s}%")
532|                    ->orWhereHas('person', function ($pq) use ($s) {
533|                        $pq->whereRaw(self::foldSeparatorsSql('f_name').' LIKE ?', ["%{$s}%"])
534|                            ->orWhereRaw(self::foldSeparatorsSql('l_name').' LIKE ?', ["%{$s}%"])
535|                            ->orWhereRaw(self::foldSeparatorsSql("CONCAT(f_name, ' ', l_name)").' LIKE ?', ["%{$s}%"]);
536|                    });
537|            });
538|        }
539|
540|        // Separate filters (AND logic)
541|        if ($this->filterType) {
542|            $type = $this->filterType;
543|            // Map common aliases to actual database values
544|            $typeAliases = ['desktop' => 'pc', 'پی‌سی' => 'pc'];
545|            $type = $typeAliases[$type] ?? $type;
546|            $type = self::normalizeForQuery($type);
547|            $query->where('type', 'LIKE', "%{$type}%");
548|        }
549|        if ($this->filterOs) {
550|            $os = self::normalizeForQuery($this->filterOs);
551|            $query->where('os', 'LIKE', "%{$os}%");
552|        }
553|        if ($this->filterCpu) {
554|            $cpu = self::normalizeForQuery($this->filterCpu);
555|            $query->where('cpu', 'LIKE', "%{$cpu}%");
556|        }
557|        if ($this->filterRam) {
558|            $ram = self::normalizeForQuery($this->filterRam);
559|            $query->where('ram', 'LIKE', "%{$ram}%");
560|        }
561|        if ($this->filterHdd) {
562|            $hdd = self::normalizeForQuery($this->filterHdd);
563|            $query->where('hdd', 'LIKE', "%{$hdd}%");
564|        }
565|        if ($this->filterShutdown !== null && $this->filterShutdown !== '') {
566|            $query->where('shutdown', $this->filterShutdown === '1');
567|        }
