543|    public function acceptTicket($ticketId): void
544|    {
545|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
546|
547|        $ticket = Ticket::whereIn('unit_id', $accessibleIds)->find($ticketId);
548|
549|        if (! $ticket) {
550|            return;
551|        }
552|
553|        // Capture old status BEFORE any changes (Plan 003: dynamic, not hardcoded)
554|        $oldStatus = $ticket->status;
555|
556|        // Plan 002: Only allow accepting from 'created' or 'forwarded' status
557|        if ($oldStatus !== 'created' && $oldStatus !== 'forwarded') {
558|            $this->dispatch('swal', [
559|                'title' => 'تیکت قبلاً پذیرفته شده است',
560|                'icon' => 'warning',
561|            ]);
562|            return;
563|        }
564|
565|        DB::transaction(function () use ($ticket, $oldStatus) {
566|            // Plan 002: Pessimistic lock to prevent concurrent accept
567|            $locked = DB::select('SELECT id, status FROM tickets WHERE id = ? FOR UPDATE', [$ticket->id]);
568|
569|            if ($locked[0]->status !== $oldStatus) {
570|                $this->dispatch('swal', [
571|                    'title' => 'تیکت قبلاً پذیرفته شده است',
572|                    'icon' => 'warning',
573|                ]);
574|                return;
575|            }
576|
577|            $ticket->update([
578|                'status' => 'accepted',
579|                'current_assignee_id' => auth()->id(),
580|                'accepted_at' => now(),
581|            ]);
582|
583|            $ticket->activities()->create([
584|                'user_id' => auth()->id(),
585|                'action' => 'accepted',
586|                'description' => 'تیکت توسط کارشناس تایید شد و مسئولیت آن پذیرفته شد.',
587|            ]);
588|
589|            // Plan 003: Use dynamic old status, not hardcoded 'created'
590|            \App\Services\ActivityLogService::updated(
591|                $ticket,
592|                ['status' => $oldStatus],
593|                ['status' => 'accepted'],
594|                "پذیرش تیکت {$ticket->ticket_code}"
595|            );
596|        });
597|
598|        $this->dispatch('swal', ['title' => 'تیکت پذیرفته شد', 'icon' => 'success']);
599|        $this->closeDetail();
600|    }
