602|    public function rejectTicket($ticketId): void
603|    {
604|        // Issue #818: no API counterpart exists, so manage_unit_tickets is the
605|        // right proxy — rejecting is the same class of state change as
606|        // completing, and the route gate alone never checked it.
607|        $this->authorize('manage_unit_tickets');
608|
609|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
610|        $ticket = Ticket::whereIn('unit_id', $accessibleIds)->find($ticketId);
611|
612|        if (! $ticket) {
613|            $this->dispatch('swal', ['title' => 'تیکت یافت نشد.', 'icon' => 'error']);
614|
615|            return;
616|        }
617|
618|        \DB::transaction(function () use ($ticket) {
619|            $ticket->update([
620|                'status' => 'rejected',
621|                'current_assignee_id' => auth()->id(),
622|            ]);
623|
624|            $ticket->activities()->create([
625|                'user_id' => auth()->id(),
626|                'action' => 'rejected',
627|                'description' => 'تیکت توسط واحد '.(auth()->user()->person?->unit?->name ?? 'بدون واحد').' رد شد.',
628|            ]);
629|        });
630|
631|        $this->dispatch('swal', ['title' => 'تیکت با موفقیت رد شد', 'icon' => 'info']);
632|        $this->closeDetail();
633|    }
