651|    public function submitAction($id = null): void
652|    {
653|        // Issue #818: same gate as forward() — this path could complete a ticket
654|        // or move it to any unit in the system under view_assigned_tickets alone.
655|        $this->authorize('manage_unit_tickets');
656|
657|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
658|        
659|        $finalId = $id ?? $this->showingTicketId;
660|        
661|        $ticket = Ticket::whereIn('unit_id', $accessibleIds)->findOrFail($finalId);
662|
663|        if ($ticket->status !== 'accepted' && !$this->targetUnitId) {
664|            $this->addError('completionNote', 'تیکت تایید نشده را نمی‌توان مختومه کرد. ابتدا ارجاع دهید یا تایید کنید.');
665|            return;
666|        }
667|
668|        $actionType = $this->targetUnitId ? 'forwarded' : 'completed';
669|
670|        $this->validate([
671|            // Issue #818: this rule did not exist here — only completionNote and
672|            // completionFiles were validated, while the branch, the unit_id and
673|            // the notification all came from targetUnitId.
674|            'targetUnitId' => $this->targetUnitRule(required: false),
675|            'completionNote' => $actionType === 'completed' ? 'required|min:5' : 'nullable|max:1000',
676|            'completionFiles' => 'nullable|array|max:5',
677|            'completionFiles.*' => 'file|mimes:jpg,jpeg,png,pdf,zip,rar,docx,xlsx|max:5120',
678|        ]);
679|
680|        // Issue #818: never write the client-supplied name into the audit trail
681|        // or the notification body.
682|        $targetUnitName = $this->resolveTargetUnitName();
683|
684|        try {
685|            DB::beginTransaction();
686|
687|            if ($actionType === 'forwarded') {
688|                $ticket->update([
689|                    'unit_id' => $this->targetUnitId,
690|                    'status' => 'forwarded',
691|                    'current_assignee_id' => null,
692|                ]);
693|                $description = "ارجاع تیکت به واحد: {$targetUnitName}";
694|                if ($this->completionNote) {
695|                    $description .= " | توضیحات: {$this->completionNote}";
696|                }
