698|
699|                // ارسال اعلان به واحد مقصد
700|                \App\Services\NotificationService::notifyUnit(
701|                    $this->targetUnitId,
702|                    'ticket_forwarded',
703|                    'تیکت ارجاع شد',
704|                    "تیکت #{$ticket->ticket_code} به واحد شما ارجاع شد - موضوع: {$ticket->subject}",
705|                    '/tickets/inbox'
706|                );
707|            } else {
708|                $ticket->update([
709|                    'status' => 'completed',
710|                    'completed_at' => now(),
711|                ]);
712|                $description = "تیکت مختومه شد. گزارش نهایی: {$this->completionNote}";
713|                $message = "تیکت با موفقیت مختومه و بسته شد.";
714|
715|                // اگر وظیفه مرتبطی دارد و تمام تیکت‌های آن وظیفه بسته شده‌اند، وظیفه را تکمیل کن
716|                if ($ticket->task_id) {
717|                    $relatedTicket = \App\Models\Ticket::where('task_id', $ticket->task_id)
718|                        ->where('status', '!=', 'completed')
719|                        ->where('id', '!=', $ticket->id)
720|                        ->count();
721|                    if ($relatedTicket === 0) {
722|                        $ticket->task->update(['is_completed' => true]);
723|                        $message .= " وظیفه مرتبط نیز تکمیل شد.";
724|                    }
725|                }
726|            }
727|
728|            $newActivity = $ticket->activities()->create([
729|                'user_id' => auth()->id(),
730|                'action' => $actionType,
731|                'description' => $description,
732|                'to_unit_id' => $this->targetUnitId ?? $ticket->unit_id,
733|            ]);
734|
735|            if ($this->completionFiles) {
736|                foreach ($this->completionFiles as $file) {
737|                    $path = $file->store('attachments', 'public');
738|                    $ticket->attachments()->create([
739|                        'user_id' => auth()->id(),
740|                        'activity_id' => $newActivity->id,
741|                        'file_path' => $path,
742|                        'file_name' => $file->getClientOriginalName(),
743|                        'file_size' => $file->getSize(),
744|                    ]);
745|                }
746|            }
747|
748|            DB::commit();
749|
750|            $this->reset(['isCompletionModalOpen', 'showingTicket', 'completionNote', 'completionFiles', 'targetUnitId', 'targetUnitName', 'unitSearch']);
751|
752|            $this->dispatch('swal', [
753|                'title' => 'عملیات موفق',
754|                'text' => $message,
755|                'icon' => 'success'
756|            ]);
757|        } catch (\Exception $e) {
758|            DB::rollBack();
