2|
3|use App\Models\MaintenanceSchedule;
4|use App\Models\Unit;
5|use App\Models\User;
6|use App\Services\AccessService;
7|use Illuminate\Pagination\LengthAwarePaginator;
8|use Illuminate\Support\Facades\Auth;
9|use Livewire\Component;
10|use Livewire\WithPagination;
11|use Mary\Traits\Toast;
12|
13|return new class extends Component
14|{
15|    use Toast;
16|    use WithPagination;
17|
18|    public string $title = '';
19|    public string $frequency = 'monthly';
20|    public int $recurrenceInterval = 1;
21|    public ?int $unitId = null;
22|
23|    public ?int $editingId = null;
24|    public string $search = '';
25|    public int $perPage = 20;
26|    public bool $showForm = false;
27|    public array $sortBy = ['column' => 'id', 'direction' => 'asc'];
28|
29|    private const SORTABLE_COLUMNS = ['id', 'title', 'frequency', 'next_due_at'];
30|
31|    public function cancelEdit(): void
32|    {
33|        $this->resetValidation();
34|        $this->reset(['title', 'frequency', 'recurrenceInterval', 'unitId', 'editingId', 'showForm']);
35|    }
36|
37|    public function startCreate(): void
38|    {
39|        $this->resetValidation();
40|        $this->reset(['title', 'frequency', 'recurrenceInterval', 'unitId', 'editingId']);
41|        $this->frequency = 'monthly';
42|        $this->recurrenceInterval = 1;
43|        $this->showForm = true;
44|    }
45|
46|    public function delete(MaintenanceSchedule $schedule): void
47|    {
48|        $this->authorize('manage_hardware');
49|
50|        if (! $this->assertScheduleInScope($schedule)) {
51|            return;
52|        }
53|
54|        try {
55|            $schedule->delete();
56|            $this->warning("«{$schedule->title}» حذف شد", 'با موفقیت', position: 'toast-bottom');
57|        } catch (\Exception $e) {
58|            $this->error('امکان حذف وجود ندارد.', position: 'toast-bottom');
59|        }
60|    }
61|
62|    public function createSchedule(): void
63|    {
64|        $this->authorize('manage_hardware');
65|
66|        $this->validate([
67|            'title' => 'required|string|max:255',
68|            'frequency' => 'required|in:daily,weekly,monthly',
69|            'recurrenceInterval' => 'required|integer|min:1',
70|            'unitId' => 'nullable|exists:units,id',
71|        ]);
72|
73|        // Creating inside a unit the actor cannot reach would plant a schedule
74|        // the `maintenance:generate-due` cron later fires tickets for.
75|        if (! $this->assertSubmittedUnitInScope()) {
76|            return;
77|        }
78|
79|        $nextDue = $this->calculateNextDue();
80|
81|        MaintenanceSchedule::create([
82|            'title' => $this->title,
83|            'frequency' => $this->frequency,
84|            'recurrence_interval' => $this->recurrenceInterval,
85|            'unit_id' => $this->unitId,
86|            'next_due_at' => $nextDue,
87|        ]);
88|
89|        $this->success("«{$this->title}» ایجاد شد", 'با موفقیت', position: 'toast-bottom');
90|        $this->cancelEdit();
91|    }
92|
93|    public function editSchedule(int $id): void
94|    {
95|        $this->authorize('manage_hardware');
96|
97|        $schedule = MaintenanceSchedule::findOrFail($id);
98|
99|        if (! $this->assertScheduleInScope($schedule)) {
100|            return;
101|        }
102|
103|        $this->resetValidation();
104|        $this->editingId = $id;
105|        $this->title = $schedule->title;
106|        $this->frequency = $schedule->frequency;
107|        $this->recurrenceInterval = $schedule->recurrence_interval;
108|        $this->unitId = $schedule->unit_id;
109|        $this->showForm = false;
110|    }
111|
112|    public function updateSchedule(): void
113|    {
114|        $this->authorize('manage_hardware');
115|
116|        $this->validate([
117|            'title' => 'required|string|max:255',
118|            'frequency' => 'required|in:daily,weekly,monthly',
119|            'recurrenceInterval' => 'required|integer|min:1',
120|            'unitId' => 'nullable|exists:units,id',
121|        ]);
122|
123|        $schedule = MaintenanceSchedule::findOrFail($this->editingId);
124|
125|        // Both halves matter: the loaded record must be in scope (else a scoped
126|        // user edits another unit's row) AND the submitted unit must be in
127|        // scope (else the same user relocates a row across the boundary).
128|        if (! $this->assertScheduleInScope($schedule)) {
129|            return;
130|        }
131|
132|        if (! $this->assertSubmittedUnitInScope()) {
133|            return;
134|        }
135|
136|        try {
