3|namespace App\Rules;
4|
5|use App\Models\Unit;
6|use Closure;
7|use Illuminate\Contracts\Validation\ValidationRule;
8|
9|/**
10| * The destination unit of a ticket — for both `tickets.create::saveTicket()`
11| * and the two inbox forwarding paths (`forward()` and `submitAction()`).
12| *
13| * Issue #818: `exists:units,id` was the whole target-side check, so a ticket
14| * could be routed to any unit in the system — including one that is
15| * `can_receive_tickets = false` or `is_active = false`, and including a unit
16| * the caller has no relation to. Forwarding is legitimately cross-unit, so the
17| * constraint is *eligibility*, not accessibility.
18| *
19| * The decision (issue #818, correction 4 — "extract the dropdown's rule" and
20| * "require `is_active`" were two different rules and only one was chosen):
21| * a destination must be BOTH `can_receive_tickets` AND `is_active`, which is
22| * the stricter of the two pickers and the only rule every surface can share.
23| * `tickets.create`'s picker already filtered both; the inbox dropdown filtered
24| * only `can_receive_tickets`, so it is aligned to this rule.
25| */
26|class TicketTargetUnit implements ValidationRule
27|{
28|    public function validate(string $attribute, mixed $value, Closure $fail): void
29|    {
30|        // Absence is `required`'s job, not ours — do not double-report it.
31|        if ($value === null || $value === '') {
32|            return;
33|        }
34|
35|        $unit = Unit::query()->whereKey($value)->first();
36|
37|        if (! $unit) {
38|            $fail('واحد انتخابی معتبر نیست.');
39|
40|            return;
41|        }
42|
43|        if (! $unit->can_receive_tickets) {
44|            $fail('این واحد امکان دریافت تیکت ندارد.');
45|
46|            return;
47|        }
48|
49|        if (! $unit->is_active) {
50|            $fail('این واحد غیرفعال است.');
51|        }
52|    }
