167|     * ستادی manager must still be offered ستادی. That is why every child is
168|     * *collected* into the result while only the not-yet-visited ones are
169|     * *queued* for the next round: skipping already-seen ids before collecting
170|     * would return an empty dropdown for exactly the accounts the rows exist
171|     * for.
172|     *
173|     * @return \Illuminate\Support\Collection<int, UnitType>
174|     */
175|    private function walkAllowedUnitTypes(): \Illuminate\Support\Collection
176|    {
177|        $visited = [$this->userUnitTypeId => true];
178|        $frontier = [$this->userUnitTypeId];
179|        $allowedUnitTypeIds = [];
180|
181|        for ($depth = 0; $depth < self::ALLOWED_UNIT_TYPES_MAX_DEPTH && $frontier !== []; $depth++) {
182|            // distinct() bounds the round's own result even if a bad import
183|            // ever inserts the same edge twice.
184|            $childUnitTypeIds = UnitTypeRelationship::whereIn('allowed_parent_unit_type_id', $frontier)
185|                ->distinct()
186|                ->pluck('child_unit_type_id')
187|                ->all();
188|
189|            $allowedUnitTypeIds = array_merge($allowedUnitTypeIds, $childUnitTypeIds);
190|
191|            $frontier = [];
192|            foreach ($childUnitTypeIds as $childUnitTypeId) {
193|                if (! isset($visited[$childUnitTypeId])) {
194|                    $visited[$childUnitTypeId] = true;
195|                    $frontier[] = $childUnitTypeId;
196|                }
197|            }
198|        }
199|
200|        $allowedUnitTypeIds = array_values(array_unique($allowedUnitTypeIds));
201|
202|        if (empty($allowedUnitTypeIds)) {
203|            return collect();
204|        }
205|
206|        return UnitType::whereIn('id', $allowedUnitTypeIds)->get();
207|    }
