273|    {
274|        $this->expanded = [];
275|        $this->lazyChildren = [];
276|    }
277|
278|    /**
279|     * Reset the tree, then reveal every match together with its ancestor chain
280|     * so a deep hit is never hidden behind a collapsed branch.
281|     */
282|    public function updatedSearch(): void
283|    {
284|        $this->expanded = [];
285|        $this->lazyChildren = [];
286|        $this->matchIds = [];
287|
288|        $accessibleIds = $this->accessibleIds();
289|        $matches = app(UnitTreeService::class)->search($this->search, $accessibleIds);
290|
291|        if ($matches->isEmpty()) {
292|            return;
293|        }
294|
295|        foreach ($matches as $matched) {
296|            $this->matchIds[(int) $matched->id] = true;
297|        }
298|
299|        $tree = app(UnitTreeService::class);
300|
301|        foreach ($matches as $unit) {
302|            $this->expanded[] = (string) $unit->id;
