304|            foreach ($tree->ancestorChain($unit, $accessibleIds) as $ancestor) {
305|                $this->expanded[] = (string) $ancestor->id;
306|            }
307|        }
308|
309|        $this->expanded = array_values(array_unique($this->expanded));
310|        $this->loadExpandedChildren();
311|    }
