320|     * @param  array<int>  $accessibleIds
321|     * @param  array<int, bool>  $visited
322|     * @return array<int, string>
323|     */
324|    protected function collectAllIds($nodes, array $accessibleIds, array $visited): array
325|    {
326|        $ids = [];
327|
328|        foreach ($nodes as $node) {
329|            if (isset($visited[(int) $node->id])) {
330|                continue;
331|            }
332|
333|            $visited[(int) $node->id] = true;
334|            $ids[] = (string) $node->id;
335|
