12|class HardwareExportController extends Controller
13|{
14|    use PersianNormalizer;
15|
16|    public function export(UnitScopedRequest $request)
17|    {
18|        $columns = array_filter(explode(',', $request->input('columns', '')));
19|        if (empty($columns)) {
20|            $columns = ['n_code', 'pc_name'];
21|        }
22|
23|        // Build query — same logic as Livewire component
24|        $accessibleIds = $request->accessibleIds();
25|        $query = Hardware::with('person.unit');
26|
27|        // Org scope
28|        if (empty($accessibleIds)) {
29|            $query->whereRaw('1 = 0');
30|        } else {
31|            $query->whereHas('person', fn ($q) => $q->whereIn('u_id', $accessibleIds));
32|        }
33|
34|        // Apply filters from query parameters
35|        // Order: normalize → escape LIKE wildcards for all text inputs
36|        if ($request->filled('search')) {
37|            $s = self::normalizeForQuery($request->search);
38|            $query->where(function ($q) use ($s) {
39|                $q->where('pc_name', 'LIKE', "%{$s}%")
40|                    ->orWhere('n_code', 'LIKE', "%{$s}%")
41|                    ->orWhere('ip_valid', 'LIKE', "%{$s}%")
42|                    ->orWhere('ip_local', 'LIKE', "%{$s}%")
43|                    ->orWhere('mac', 'LIKE', "%{$s}%")
44|                    ->orWhere('comments', 'LIKE', "%{$s}%")
45|                    ->orWhereHas('person', function ($pq) use ($s) {
46|                        $pq->where('f_name', 'LIKE', "%{$s}%")
47|                            ->orWhere('l_name', 'LIKE', "%{$s}%")
48|                            ->orWhereRaw("CONCAT(f_name, ' ', l_name) LIKE ?", ["%{$s}%"]);
49|                    });
50|            });
51|        }
52|
53|        if ($request->filled('type')) {
54|            $typeAliases = ['desktop' => 'pc', 'پی‌سی' => 'pc'];
55|            $type = $typeAliases[$request->type] ?? $request->type;
56|            $type = self::normalizeForQuery($type);
57|            $query->where('type', 'LIKE', "%{$type}%");
58|        }
59|        if ($request->filled('os')) {
60|            $os = self::normalizeForQuery($request->os);
61|            $query->where('os', 'LIKE', "%{$os}%");
62|        }
63|        if ($request->filled('cpu')) {
64|            $cpu = self::normalizeForQuery($request->cpu);
65|            $query->where('cpu', 'LIKE', "%{$cpu}%");
66|        }
67|        if ($request->filled('ram')) {
68|            $ram = self::normalizeForQuery($request->ram);
69|            $query->where('ram', 'LIKE', "%{$ram}%");
70|        }
71|        if ($request->filled('hdd')) {
72|            $hdd = self::normalizeForQuery($request->hdd);
73|            $query->where('hdd', 'LIKE', "%{$hdd}%");
74|        }
75|        if ($request->filled('shutdown')) {
76|            $query->where('shutdown', $request->shutdown === '1');
77|        }
78|        if ($request->filled('net_type')) {
79|            $netType = self::normalizeForQuery($request->net_type);
80|            $query->where('net_type', 'LIKE', "%{$netType}%");
81|        }
82|        if ($request->filled('mark')) {
83|            $query->where('mark', $request->mark === '1');
84|        }
85|        if ($request->filled('person')) {
86|            $normalized = self::normalizeForQuery($request->person);
87|            $query->whereHas('person', function ($q) use ($normalized) {
88|                $q->where('f_name', 'LIKE', "%{$normalized}%")
89|                    ->orWhere('l_name', 'LIKE', "%{$normalized}%")
90|                    ->orWhere('n_code', 'LIKE', "%{$normalized}%")
91|                    ->orWhereRaw("CONCAT(f_name, ' ', l_name) LIKE ?", ["%{$normalized}%"]);
92|            });
93|        }
94|        if ($request->filled('unit')) {
95|            $term = self::foldedTerm($request->unit);
96|            $query->whereHas('person.unit', function ($q) use ($term) {
97|                $q->whereRaw(self::foldSeparatorsSql('name').' LIKE ?', ["%{$term}%"]);
98|            });
99|        }
100|        if ($request->filled('semat')) {
101|            $term = self::foldedTerm($request->semat);
102|            $query->whereHas('person.semat', function ($q) use ($term) {
103|                $q->whereRaw(self::foldSeparatorsSql('name').' LIKE ?', ["%{$term}%"]);
104|            });
105|        }
106|
107|        $query->orderByDesc('id');
108|
109|        $filename = 'hardware-'.now()->format('Ymd-His');
110|
111|        return Excel::download(
112|            new HardwareExport($query, $columns),
113|            "{$filename}.xlsx"
114|        );
115|    }
