18| * @property string $content
19| * @property string $priority
20| * @property string $status
21| * @property int|null $current_assignee_id
22| * @property int $task_id
23| * @property Carbon|null $deadline
24| * @property Carbon|null $accepted_at
25| * @property Carbon|null $completed_at
26| * @property Carbon|null $created_at
27| * @property Carbon|null $updated_at
28| * @property-read string $status_name
29| * @property-read array $waiting_duration
30| * @property-read Unit $unit
31| * @property-read User $user
32| * @property-read User|null $assignee
33| * @property-read Todo|null $task
34| * @property-read Collection $attachments
35| * @property-read Collection $activities
36| * @property-read Collection $comments
37| */
38|class Ticket extends Model
39|{
40|    use HasOrganizationalScope;
41|
42|    protected $fillable = [
43|        'ticket_code',
44|        'user_id',
45|        'unit_id',
46|        'subject',
47|        'content',
48|        'priority',
49|        'status',
50|        'task_id',
51|        'deadline',
52|        'current_assignee_id',
53|        'accepted_at',
54|        'completed_at',
55|    ];
56|
57|    /** @var array<string, string> */
58|    protected $casts = [
59|        'deadline' => 'datetime',
60|        'accepted_at' => 'datetime',
61|        'completed_at' => 'datetime',
62|    ];
63|
64|    public function canBeCompleted()
65|    {
66|        return $this->status === 'accepted';
67|    }
68|
69|    public function getWaitingDurationAttribute()
70|    {
71|        $totalHours = floor($this->created_at->diffInHours(now()));
72|
73|        if ($totalHours < 1) {
74|            return ['text' => 'کمتر از ۱ ساعت', 'class' => 'bg-emerald-100 text-emerald-700'];
75|        }
76|
77|        if ($totalHours < 24) {
78|            return ['text' => $totalHours.' ساعت', 'class' => 'bg-emerald-100 text-emerald-700'];
79|        } elseif ($totalHours < 48) {
80|            return ['text' => '۱ روز و '.($totalHours - 24).' ساعت', 'class' => 'bg-orange-100 text-orange-700'];
81|        } else {
82|            $days = floor($totalHours / 24);
83|
84|            return ['text' => $days.' روز و '.($totalHours % 24).' ساعت', 'class' => 'bg-red-100 text-red-700 animate-pulse'];
85|        }
86|    }
87|
88|    // تعریف status_name برای نمایش فارسی وضعیت‌های تیکت
89|    public function getStatusNameAttribute()
90|    {
91|        return match ($this->status) {
92|            'created' => 'جدید ',
93|            'forwarded' => 'ارجاع شده',
94|            'accepted' => 'در حال پیگیری',
95|            'completed' => 'پایان یافته',
96|            'rejected' => 'رد شده',
97|            default => 'نامشخص',
98|        };
99|    }
100|
101|    public function unit(): BelongsTo
102|    {
103|        return $this->belongsTo(Unit::class);
104|    }
105|
106|    // رابطه با وظیفه مرتبط
107|    public function task(): BelongsTo
108|    {
109|        return $this->belongsTo(Todo::class, 'task_id');
110|    }
111|
112|    public function user(): BelongsTo
113|    {
114|        return $this->belongsTo(User::class, 'user_id');
115|    }
116|
117|    // رابطه با شخصی که تیکت به او واگذار شده
118|    public function assignee(): BelongsTo
119|    {
120|        return $this->belongsTo(User::class, 'current_assignee_id');
121|    }
122|
123|    public function attachments(): HasMany
124|    {
125|        return $this->hasMany(Attachment::class);
126|    }
127|
128|    // رابطه با فعالیت‌ها
129|    public function activities()
130|    {
131|        // دقت کنید که در مایگریشن جدید نام فیلد را ticket_id گذاشتیم
132|        return $this->hasMany(TaskActivity::class, 'ticket_id');
