3|namespace App\Exports;
4|
5|use Illuminate\Database\Eloquent\Builder;
6|use Illuminate\Support\Collection;
7|use Maatwebsite\Excel\Concerns\FromCollection;
8|use Maatwebsite\Excel\Concerns\ShouldAutoSize;
9|use Maatwebsite\Excel\Concerns\WithChunkReading;
10|use Maatwebsite\Excel\Concerns\WithHeadings;
11|use Maatwebsite\Excel\Concerns\WithMapping;
12|use Maatwebsite\Excel\Concerns\WithTitle;
13|use Morilog\Jalali\Jalalian;
14|
15|class HardwareExport implements FromCollection, ShouldAutoSize, WithChunkReading, WithHeadings, WithMapping, WithTitle
16|{
17|    protected Builder $query;
18|
19|    protected array $columns;
20|
21|    protected int $lastId = 0;
22|
23|    protected int $chunkSize = 500;
24|
25|    /**
26|     * Column definitions: key => ['label' => Persian, 'accessor' => callable|null]
27|     */
28|    protected array $columnDefs = [
29|        'n_code' => ['label' => 'کد ملی'],
30|        'pc_name' => ['label' => 'نام دستگاه'],
31|        'type' => ['label' => 'نوع'],
32|        'os' => ['label' => 'سیستم عامل'],
33|        'ip_valid' => ['label' => 'IP عمومی'],
34|        'ip_local' => ['label' => 'IP محلی'],
35|        'mac' => ['label' => 'MAC'],
36|        'net_type' => ['label' => 'نوع اتصال'],
37|        'switch' => ['label' => 'سوئیچ'],
38|        'port' => ['label' => 'پورت'],
39|        'vlan' => ['label' => 'VLAN'],
40|        'motherboard' => ['label' => 'مادربورد'],
41|        'cpu' => ['label' => 'CPU'],
42|        'ram' => ['label' => 'RAM'],
43|        'hdd' => ['label' => 'HDD/SSD'],
44|        'shutdown' => ['label' => 'وضعیت روشن/خاموش'],
45|        'mark' => ['label' => 'علامت'],
46|        'comments' => ['label' => 'توضیحات'],
47|        'clean_at' => ['label' => 'تاریخ نظافت'],
48|        'person_name' => ['label' => 'صاحب'],
49|        'unit_name' => ['label' => 'واحد'],
50|        'status' => ['label' => 'وضعیت'],
51|    ];
52|
53|    public function __construct(Builder $query, array $columns)
54|    {
55|        $this->query = $query;
56|        $this->columns = array_intersect($columns, array_keys($this->columnDefs));
57|    }
58|
59|    /**
60|     * Fallback for small datasets (used by FromCollection).
61|     */
62|    public function collection(): Collection
63|    {
64|        return $this->query->get();
65|    }
66|
67|    public function chunkSize(): int
68|    {
69|        return $this->chunkSize;
70|    }
71|
72|    public function headings(): array
73|    {
74|        return array_map(
75|            fn ($key) => $this->columnDefs[$key]['label'],
76|            $this->columns
77|        );
78|    }
79|
80|    public function map($hardware): array
81|    {
82|        return array_map(
83|            fn ($key) => $this->resolveValue($hardware, $key),
84|            $this->columns
85|        );
86|    }
87|
88|    protected function resolveValue($hardware, string $key): mixed
89|    {
90|        return match ($key) {
91|            'person_name' => $hardware->person
92|                ? trim($hardware->person->f_name.' '.$hardware->person->l_name)
93|                : '-',
94|            'unit_name' => $hardware->person?->unit?->name ?? '-',
95|            'shutdown' => $hardware->shutdown ? 'روشن' : 'خاموش',
96|            'mark' => $hardware->mark ? 'علامت‌دار' : '-',
97|            'clean_at' => $hardware->clean_at
98|                ? Jalalian::fromCarbon($hardware->clean_at)->format('Y/m/d')
99|                : '-',
100|            'comments' => $hardware->comments ?? '-',
101|            'status' => $hardware->mark
102|                ? 'علامت'
103|                : ($hardware->shutdown ? 'فعال' : 'خاموش'),
104|            default => $hardware->{$key} ?? '-',
105|        };
106|    }
107|
108|    public function title(): string
109|    {
110|        return 'شناسنامه سخت‌افزار';
