10|use Illuminate\Database\Eloquent\SoftDeletes;
11|
12|/**
13| * @property int $id
14| * @property int $ticket_id
15| * @property int $user_id
16| * @property int|null $parent_id
17| * @property string $body
18| * @property string $body_html
19| * @property bool $is_system
20| * @property string $system_event
21| * @property Carbon|null $deleted_at
22| * @property Carbon|null $created_at
23| * @property Carbon|null $updated_at
24| * @property-read Ticket $ticket
25| * @property-read User $user
26| * @property-read TicketComment|null $parent
27| * @property-read Collection<int, TicketComment> $children
28| * @property-read Collection<int, TicketCommentReaction> $reactions
29| *
30| * @method static \Illuminate\Database\Eloquent\Builder<static> where(string $column, mixed $value)
31| */
32|class TicketComment extends Model
33|{
34|    use SoftDeletes;
35|
36|    protected $fillable = [
37|        'ticket_id',
38|        'user_id',
39|        'parent_id',
40|        'body',
41|        'body_html',
42|        'is_system',
43|        'system_event',
44|    ];
45|
46|    protected $casts = [
47|        'is_system' => 'boolean',
48|    ];
49|
50|    /**
51|     * Get the ticket that owns the comment.
52|     */
53|    public function ticket(): BelongsTo
54|    {
55|        return $this->belongsTo(Ticket::class);
56|    }
57|
58|    /**
59|     * Get the user that authored the comment.
60|     */
61|    public function user(): BelongsTo
62|    {
63|        return $this->belongsTo(User::class);
64|    }
65|
66|    /**
67|     * Get the parent comment (for threaded replies).
68|     */
69|    public function parent(): BelongsTo
70|    {
71|        return $this->belongsTo(TicketComment::class, 'parent_id');
72|    }
73|
74|    /**
75|     * Get child comments (replies).
76|     */
77|    public function children(): HasMany
78|    {
79|        return $this->hasMany(TicketComment::class, 'parent_id')->with('user.person');
80|    }
81|
82|    /**
83|     * Get reactions on this comment.
84|     */
85|    public function reactions(): HasMany
86|    {
87|        return $this->hasMany(TicketCommentReaction::class, 'comment_id');
88|    }
89|
90|    /**
91|     * Scope: only root comments (no parent).
92|     */
93|    public function scopeRoot($query)
94|    {
95|        return $query->whereNull('parent_id');
96|    }
97|
98|    /**
99|     * Scope: only system comments.
100|     */
101|    public function scopeSystem($query)
102|    {
103|        return $query->where('is_system', true);
104|    }
105|
106|    /**
107|     * Scope: only user comments (not system).
108|     */
109|    public function scopeUser($query)
110|    {
111|        return $query->where('is_system', false);
112|    }
113|
114|    /**
115|     * Scope: with reaction counts.
116|     */
117|    public function scopeWithReactionCounts($query)
118|    {
119|        return $query->withCount(['reactions as reaction_counts' => function ($q) {
120|            $q->selectRaw('reaction, count(*)')
121|                ->groupBy('reaction');
122|        }]);
123|    }
124|
125|    /**
126|     * Check if comment can be edited (author only, within 15 minutes).
127|     */
128|    public function canBeEditedBy(User $user): bool
129|    {
130|        if ($this->user_id !== $user->id) {
131|            return false;
132|        }
133|
134|        return $this->created_at->diffInMinutes(now()) <= 15;
135|    }
136|
137|    /**
138|     * Check if comment can be deleted (author or admin).
139|     */
140|    public function canBeDeletedBy(User $user): bool
141|    {
142|        if ($this->user_id === $user->id) {
143|            return true;
144|        }
145|
146|        return $user->can('manage_unit_tickets') || $user->hasRole('admin');
147|    }
