{"content": "1|<?php
2|
3|namespace App\Imports;
4|
5|use App\Models\Hardware;
6|use App\Models\Person;
7|use App\Services\AccessService;
8|use Illuminate\Support\Collection;
9|use Maatwebsite\Excel\Concerns\ToCollection;
10|use Maatwebsite\Excel\Concerns\WithCustomCsvSettings;
11|use Maatwebsite\Excel\Concerns\WithHeadingRow;
12|
13|class HardwareImport implements ToCollection, WithCustomCsvSettings, WithHeadingRow
14|{
15|    private array $accessibleUnitIds = [];
16|
17|    private array $existingRecords = [];
18|
19|    private array $existingPersons = [];
20|
21|    private string $compareKey = 'both'; // 'pc_name', 'mac', 'both'
22|
23|    private array $selectedActions = [];
24|
25|    private array $importResults = [
26|        'created' => 0,
27|        'updated' => 0,
28|        'skipped' => 0,
29|        'errors' => [],
30|        'changes' => [],
31|        'preview' => [],
32|    ];
33|
34|    public function __construct()
35|    {
36|        $this->accessibleUnitIds = app(AccessService::class)->accessibleUnitIds();
37|    }
38|
39|    public function setCompareKey(string $key): void
40|    {
41|        $this->compareKey = $key;
42|    }
43|
44|    public function setAccessibleUnitIds(array $ids): void
45|    {
46|        $this->accessibleUnitIds = $ids;
47|    }
48|
49|    public function setSelectedActions(array $actions): void
50|    {
51|        $this->selectedActions = $actions;
52|    }
53|
54|    public function collection(Collection $rows): void
55|    {
56|        // Pre-load existing hardware records by pc_name and mac for comparison
57|        $this->loadExistingRecords();
58|
59|        // First pass: build preview data
60|        foreach ($rows as $index => $row) {
61|            $this->buildPreview($row->toArray(), $index + 2); // +2 for header row and 1-indexed
62|        }
63|
64|        // Second pass: apply selected actions if provided
65|        if (! empty($this->selectedActions)) {
66|            // Reset counters since they were incremented during preview pass
67|            // The actual import will increment them correctly
68|            $this->importResults['created'] = 0;
69|            $this->importResults['updated'] = 0;
70|            $this->importResults['skipped'] = 0;
71|            $this->importResults['changes'] = [];
72|
73|            foreach ($rows as $index => $row) {
74|                $this->applySelectedAction($row->toArray(), $index + 2);
75|            }
76|        }
77|    }
78|
79|    private function loadExistingRecords(): void
80|    {
81|        $query = Hardware::query();
82|
83|        // Apply organizational scope — UNCONDITIONAL (issue #839 / Plan 50).
84|        // `[]` is a legitimate `AccessService` output, so an emptiness guard
85|        // here would index EVERY hardware row org-wide by pc_name / mac and a
86|        // matching CSV row would rewrite a record the actor cannot see.
87|        // An empty array compiles to `0 = 1` (fail-closed by construction).
88|        $query->whereHas('person', function ($q) {
89|            $q->whereIn('u_id', $this->accessibleUnitIds);
90|        });
91|
92|        $hardwares = $query->get(['id', 'pc_name', 'mac', 'n_code', 'type', 'os', 'ip_valid', 'ip_local', 'net_type', 'switch', 'port', 'shutdown', 'vlan', 'motherboard', 'cpu', 'ram', 'hdd', 'comments', 'mark', 'clean_at']);
93|
94|        foreach ($hardwares as $hw) {
95|            // Index by pc_name and mac for quick lookup
96|            if ($hw->pc_name) {
97|                $this->existingRecords['pc_name'][$hw->pc_name] = $hw;
98|            }
99|            if ($hw->mac) {
100|                $this->existingRecords['mac'][$hw->mac] = $hw;
101|            }
102|        }
103|
104|        // Pre-load all persons in accessible units to avoid N+1 queries
105|        $this->loadExistingPersons();
106|    }
107|
108|    private function loadExistingPersons(): void
109|    {
110|        $query = Person::query();
111|
112|        // Apply organizational scope — UNCONDITIONAL (issue #839). `[]` must not
113|        // fall through to "every person in the org".
114|        $query->whereIn('u_id', $this->accessibleUnitIds);
115|
116|        $persons = $query->get(['n_code', 'u_id', 'f_name', 'l_name']);
117|
118|        foreach ($persons as $person) {
119|            $this->existingPersons[$person->n_code] = $person;
120|        }
121|    }
122|
123|    private function applySelectedAction($row, int $rowNumber): void
124|    {
125|        // Check if this row has a selected action
126|        $actionKey = "row_{$rowNumber}";
127|        if (! isset($this->selectedActions[$actionKey])) {
128|            return;
129|        }
130|
131|        $action = $this->selectedActions[$actionKey];
132|        if ($action === 'skip') {
133|            return;
134|        }
135|
136|        $this->processRow($row, $rowNumber, $action, true);
137|    }
138|
139|    private function buildPreview($row, int $rowNumber): void
140|    {
141|        // Map CSV columns to hardware fields
142|        $data = $this->mapRowToData($row);
143|
144|        // Validate required fields
145|        if (empty($data['n_code']) || empty($data['pc_name'])) {
146|            $this->importResults['preview'][] = [
147|                'row' => $rowNumber,
148|                'status' => 'error',
149|                'message' => 'فیلدهای اجباری n_code و pc_name خالی هستند',
150|                'data' => $data,
151|            ];
152|            $this->importResults['skipped']++;
153|
154|            return;
155|        }
156|
157|        // Verify person exists and is in accessible units
158|        $person = $this->existingPersons[$data['n_code']] ?? null;
159|        if (! $person) {
160|            $this->importResults['preview'][] = [
161|                'row' => $rowNumber,
162|                'status' => 'error',
163|                'message' => "پرسنل با کد ملی {$data['n_code']} یافت نشد",
164|                'data' => $data,
165|            ];
166|            $this->importResults['skipped']++;
167|
168|            return;
169|        }
170|
171|        // UNCONDITIONAL membership test (issue #839): the `! empty(...)` conjunct
172|        // made this `! empty([]) && ...` = false, i.e. ACCEPT the row. Under an
173|        // empty scope `$this->existingPersons` is empty, so the "person not
174|        // found" check above already rejected it — defence in depth.
175|        if (! in_array($person->u_id, $this->accessibleUnitIds)) {
176|            $this->importResults['preview'][] = [
177|                'row' => $rowNumber,
178|                'status' => 'error',
179|                'message' => "پرسنل {$data['n_code']} در واحدهای قابل دسترس شما نیست",
180|                'data' => $data,
181|            ];
182|            $this->importResults['skipped']++;
183|
184|            return;
185|        }
186|
187|        // Find existing record
188|        $existing = $this->findExistingRecord($data);
189|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
190|
191|        if ($existing) {
192|            $changes = $this->detectChanges($existing['record'], $data);
193|
194|            if (! empty($changes)) {
195|                $this->importResults['preview'][] = [
196|                    'row' => $rowNumber,
197|                    'status' => 'update',
198|                    'id' => $existing['record']->id,
199|                    'pc_name' => $existing['record']->pc_name,
200|                    'match_key' => $matchKey,
201|                    'changes' => $changes,
202|                    'person' => $person->f_name.' '.$person->l_name,
203|                    'data' => $data,
204|                ];
205|                $this->importResults['updated']++;
206|            } else {
207|                $this->importResults['preview'][] = [
208|                    'row' => $rowNumber,
209|                    'status' => 'unchanged',
210|                    'id' => $existing['record']->id,
211|                    'pc_name' => $existing['record']->pc_name,
212|                    'match_key' => $matchKey,
213|                    'message' => 'بدون تغییر',
214|                    'person' => $person->f_name.' '.$person->l_name,
215|                    'data' => $data,
216|                ];
217|                $this->importResults['skipped']++;
218|            }
219|        } else {
220|            $this->importResults['preview'][] = [
221|                'row' => $rowNumber,
222|                'status' => 'create',
223|                'pc_name' => $data['pc_name'],
224|                'person' => $person->f_name.' '.$person->l_name,
225|                'data' => $data,
226|            ];
227|            $this->importResults['created']++;
228|        }
229|    }
230|
231|    private function findExistingRecord(array $data): ?array
232|    {
233|        $existing = null;
234|        $matchKey = null;
235|
236|        if (in_array($this->compareKey, ['pc_name', 'both']) && ! empty($data['pc_name']) && isset($this->existingRecords['pc_name'][$data['pc_name']])) {
237|            $existing = $this->existingRecords['pc_name'][$data['pc_name']];
238|            $matchKey = 'pc_name';
239|        } elseif (in_array($this->compareKey, ['mac', 'both']) && ! empty($data['mac']) && isset($this->existingRecords['mac'][$data['mac']])) {
240|            $existing = $this->existingRecords['mac'][$data['mac']];
241|            $matchKey = 'mac';
242|        }
243|
244|        if ($existing) {
245|            return ['record' => $existing, 'key' => $matchKey];
246|        }
247|
248|        return null;
249|    }
250|
251|    private function mapRowToData(array $row): array
252|    {
253|        return [
254|            'n_code' => $this->clean($row['n_code'] ?? null),
255|            'pc_name' => $this->clean($row['pc_name'] ?? null),
256|            'type' => $this->clean($row['type'] ?? null),
257|            'os' => $this->clean($row['os'] ?? null),
258|            'ip_valid' => $this->clean($row['ip_valid'] ?? null),
259|            'ip_local' => $this->clean($row['ip_local'] ?? null),
260|            'mac' => $this->clean($row['mac'] ?? null),
261|            'net_type' => $this->clean($row['net_type'] ?? null),
262|            'switch' => $this->clean($row['switch'] ?? null),
263|            'port' => $this->clean($row['port'] ?? null),
264|            'shutdown' => $this->parseBoolean($row['shutdown'] ?? null) ?? false,
265|            'vlan' => $this->clean($row['vlan'] ?? null),
266|            'motherboard' => $this->clean($row['motherboard'] ?? null),
267|            'cpu' => $this->clean($row['cpu'] ?? null),
268|            'ram' => $this->clean($row['ram'] ?? null),
269|            'hdd' => $this->clean($row['hdd'] ?? null),
270|            'comments' => $this->clean($row['comments'] ?? null),
271|            'mark' => $this->parseBoolean($row['mark'] ?? null) ?? false,
272|            'clean_at' => $this->parseDate($row['clean_at'] ?? null),
273|        ];
274|    }
275|
276|    private function processRow(array $row, int $rowNumber, string $action = 'auto', bool $isConfirmation = false): void
277|    {
278|        $data = $this->mapRowToData($row);
279|
280|        // Validate required fields
281|        if (empty($data['n_code']) || empty($data['pc_name'])) {
282|            $this->importResults['errors'][] = [
283|                'row' => $rowNumber,
284|                'error' => 'Missing required fields: n_code and pc_name are required',
285|                'data' => $data,
286|            ];
287|            $this->importResults['skipped']++;
288|
289|            return;
290|        }
291|
292|        // Verify person exists and is in accessible units
293|        $person = $this->existingPersons[$data['n_code']] ?? null;
294|        if (! $person) {
295|            $this->importResults['errors'][] = [
296|                'row' => $rowNumber,
297|                'error' => "Person with n_code {$data['n_code']} not found",
298|                'data' => $data,
299|            ];
300|            $this->importResults['skipped']++;
301|
302|            return;
303|        }
304|
305|        // UNCONDITIONAL membership test (issue #839): the `! empty(...)` conjunct
306|        // made this `! empty([]) && ...` = false, i.e. ACCEPT the row.
307|        if (! in_array($person->u_id, $this->accessibleUnitIds)) {
308|            $this->importResults['errors'][] = [
309|                'row' => $rowNumber,
310|                'error' => "Person {$data['n_code']} is not in your accessible units",
311|                'data' => $data,
312|            ];
313|            $this->importResults['skipped']++;
314|
315|            return;
316|        }
317|
318|        // Find existing record by pc_name or mac
319|        $existing = $this->findExistingRecord($data);
320|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
321|
322|        if ($existing) {
323|            // Check for changes
324|            $changes = $this->detectChanges($existing['record'], $data);
325|
326|            if (! empty($changes)) {
327|                $this->importResults['changes'][] = [
328|                    'row' => $rowNumber,
329|                    'id' => $existing['record']->id,
330|                    'pc_name' => $existing['record']->pc_name,
331|                    'match_key' => $matchKey,
332|                    'changes' => $changes,
333|                ];
334|
335|                // Update the record
336|                if ($action === 'update' || $action === 'auto') {
337|                    $existing['record']->update($data);
338|                    $this->importResults['updated']++;
339|                }
340|            } else {
341|                $this->importResults['skipped']++;
342|            }
343|        } else {
344|            // Create new record
345|            if ($action === 'create' || $action === 'auto') {
346|                Hardware::create($data);
347|                $this->importResults['created']++;
348|            }
349|        }
350|    }
351|
352|    private function detectChanges(Hardware $existing, array $newData): array
353|    {
354|        $changes = [];
355|        $compareFields = [
356|            'n_code', 'type', 'os', 'ip_valid', 'ip_local', 'mac',
357|            'net_type', 'switch', 'port', 'shutdown', 'vlan',
358|            'motherboard', 'cpu', 'ram', 'hdd', 'comments', 'mark', 'clean_at',
359|        ];
360|
361|        foreach ($compareFields as $field) {
362|            $oldValue = $existing->$field;
363|            $newValue = $newData[$field] ?? null;
364|
365|            // Normalize for comparison
366|            $oldNormalized = $this->normalizeForComparison($oldValue);
367|            $newNormalized = $this->normalizeForComparison($newValue);
368|
369|            if ($oldNormalized !== $newNormalized) {
370|                $changes[$field] = [
371|                    'old' => $oldValue,
372|                    'new' => $newValue,
373|                ];
374|            }
375|        }
376|
377|        return $changes;
378|    }
379|
380|    private function normalizeForComparison($value): ?string
381|    {
382|        if ($value === null || $value === '' || $value === '\\\\\\\\\\\\\\\\N') {
383|            return '0'; // Treat null/empty as false for boolean comparison
384|        }
385|        if (is_bool($value)) {
386|            return $value ? '1' : '0';
387|        }
388|        // Handle boolean false/0 values that come from database
389|        if ($value === false || $value === 0 || $value === '0') {
390|            return '0';
391|        }
392|        if ($value === true || $value === 1 || $value === '1') {
393|            return '1';
394|        }
395|
396|        return trim((string) $value);
397|    }
398|
399|    private function parseBoolean($value): ?bool
400|    {
401|        if ($value === null || $value === '' || $value === '\\N') {
402|            return null;
403|        }
404|        $val = strtolower(trim((string) $value));
405|
406|        return in_array($val, ['1', 'true', 'yes', 'on', 'بله', 'تایید']);
407|    }
408|
409|    private function parseDate($value): ?string
410|    {
411|        if ($value === null || $value === '' || $value === '\\N') {
412|            return null;
413|        }
414|        $value = trim((string) $value);
415|        if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $value)) {
416|            return $value;
417|        }
418|
419|        return null;
420|    }
421|
422|    private function clean($value): ?string
423|    {
424|        if ($value === null || $value === '' || $value === '\\N' || trim((string) $value) === '') {
425|            return null;
426|        }
427|
428|        return trim((string) $value);
429|    }
430|
