5|use App\Models\Notification;
6|use App\Models\Notification as NotificationModel;
7|use App\Models\User;
8|use Illuminate\Support\Facades\Cache;
9|use Illuminate\Support\Str;
10|
11|class NotificationService
12|{
13|    public static function send(
14|        int $userId,
15|        string $type,
16|        string $title,
17|        ?string $body = null,
18|        string $icon = 'o-bell',
19|        string $color = 'text-info',
20|        ?string $url = null,
21|        ?array $data = null
22|    ): NotificationModel {
23|        $notification = NotificationModel::create([
24|            'user_id' => $userId,
25|            'type' => $type,
26|            'title' => $title,
27|            'body' => $body,
28|            'icon' => $icon,
29|            'color' => $color,
30|            'url' => $url,
31|            'data' => $data,
32|        ]);
33|
34|        // Issue #393: invalidate the bell component cache for the recipient
35|        Cache::forget("notifications:user:{$userId}");
36|
37|        return $notification;
38|    }
39|
40|    public static function notifyUnit(int $unitId, string $type, string $title, ?string $body = null, ?string $url = null): void
41|    {
42|        $userIds = User::whereHas('units', fn ($q) => $q->where('units.id', $unitId))
43|            ->pluck('id');
44|
45|        if ($userIds->isEmpty()) {
46|            return;
47|        }
48|
49|        // Batch insert for better performance (must include UUID since insert() bypasses model boot)
50|        $notifications = $userIds->map(fn ($userId) => [
51|            'id' => Str::uuid(),
52|            'user_id' => $userId,
53|            'type' => $type,
54|            'title' => $title,
55|            'body' => $body,
56|            'icon' => 'o-ticket',
57|            'color' => 'text-info',
58|            'url' => $url,
59|            'created_at' => now(),
60|            'updated_at' => now(),
61|        ])->toArray();
62|
63|        Notification::insert($notifications);
64|
65|        // Issue #393: invalidate bell cache for all recipients
66|        foreach ($userIds as $userId) {
67|            Cache::forget("notifications:user:{$userId}");
68|        }
69|    }
