3|namespace App\Console\Commands;
4|
5|use App\Models\MaintenanceSchedule;
6|use App\Models\Ticket;
7|use Illuminate\Console\Command;
8|use Illuminate\Support\Str;
9|
10|class GenerateDueMaintenance extends Command
11|{
12|    protected $signature = 'maintenance:generate-due {--dry-run : فقط نمایش موارد سررسید شده، بدون ایجاد تیکت}';
13|
14|    protected $description = 'Generate due maintenance tickets from preventive maintenance schedules';
15|
16|    public function handle(): int
17|    {
18|        $dryRun = (bool) $this->option('dry-run');
19|
20|        $schedules = MaintenanceSchedule::query()
21|            ->where(function ($q) {
22|                $q->whereNull('next_due_at')
23|                    ->orWhere('next_due_at', '<=', now());
24|            })
25|            ->get();
26|
27|        $this->info('Generating due maintenance tasks...');
28|        $this->line("  Found {$schedules->count()} maintenance schedule(s) due.");
29|
30|        if ($dryRun) {
31|            $this->warn('  Dry run — no tickets were created.');
32|            $this->info('Maintenance task generation complete.');
33|
34|            return 0;
35|        }
36|
37|        $created = 0;
38|        foreach ($schedules as $schedule) {
39|            // Issue #533: idempotency guard — skip if an open ticket already exists
40|            // for this schedule (prevents duplicates on scheduler overlap or crash)
41|            $existingTicket = Ticket::where('unit_id', $schedule->unit_id)
42|                ->where('subject', $schedule->title)
43|                ->where('status', '!=', 'completed')
44|                ->where('created_at', '>=', now()->subDay())
45|                ->exists();
46|
47|            if ($existingTicket) {
48|                $this->warn("  Skipping schedule #{$schedule->id} — open ticket already exists.");
49|                // Still advance the schedule to avoid getting stuck
50|                $interval = max(1, (int) $schedule->recurrence_interval);
51|                $next = match ($schedule->frequency) {
52|                    'daily' => now()->addDays($interval),
53|                    'weekly' => now()->addWeeks($interval),
54|                    'monthly' => now()->addMonths($interval),
55|                    default => now()->addMonths($interval),
56|                };
57|                $schedule->update([
58|                    'last_generated_at' => now(),
59|                    'next_due_at' => $next,
60|                ]);
61|
62|                continue;
63|            }
64|
65|            $ticket = Ticket::create([
66|                'ticket_code' => 'T-'.strtoupper(Str::random(8)),
67|                'subject' => $schedule->title,
68|                'content' => 'Generated from maintenance schedule #'.$schedule->id,
69|                'status' => 'created',
70|                'priority' => 'medium',
71|                'unit_id' => $schedule->unit_id,
72|            ]);
73|
74|            $interval = max(1, (int) $schedule->recurrence_interval);
75|            $next = match ($schedule->frequency) {
76|                'daily' => now()->addDays($interval),
77|                'weekly' => now()->addWeeks($interval),
78|                'monthly' => now()->addMonths($interval),
79|                default => now()->addMonths($interval),
80|            };
81|
82|            $schedule->update([
83|                'last_generated_at' => now(),
84|                'next_due_at' => $next,
85|            ]);
86|
87|            $created++;
88|        }
89|
90|        $this->line("  Created {$created} maintenance ticket(s).");
91|        $this->info('Maintenance task generation complete.');
92|
93|        return 0;
94|    }
