169|            {{-- #817: out-of-scope mounts render no actionable controls. --}}
170|            @if($unit)
171|            <button type="button" class="btn btn-primary" onclick="saveMapBoundary()">
172|                <x-icon name="o-check" class="w-5 h-5"/>
173|                ذخیره
