191|        filter: invert(100%) hue-rotate(180deg) brightness(100%) contrast(100%);
192|    }
193|</style>
194|@endassets
195|
196|@script
197|<script>
198|    var mapTileTemplate = @js(config('map.tile_url_template', 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'));
199|
200|    function initUnitMap() {
201|        var unitMap = L.map('unitMap').setView([36.558188, 48.716125], 8);
202|
203|        L.tileLayer(mapTileTemplate, {
204|            attribution: '&copy; Health-Dashboard',
205|            className: 'map-tiles'
206|        }).addTo(unitMap);
207|
208|        var drawnItems = new L.FeatureGroup();
209|        window._drawnItems = drawnItems;
210|        unitMap.addLayer(drawnItems);
211|
212|        var existingLayer = null;
213|        var initialGeojson = @js($geojson);
214|
215|        if (initialGeojson) {
216|            try {
217|                var data = typeof initialGeojson === 'string' ? JSON.parse(initialGeojson) : initialGeojson;
218|
219|                // #702: boundaries are stored as MultiPolygon (PostGIS) and
220|                // Boundary::getGeojsonAttribute() returns ST_AsGeoJSON's BARE
221|                // geometry ({type, coordinates}) — not a GeoJSON Feature. Two bugs
222|                // followed from that:
223|                //   1. L.geoJSON() was handed a geometry with no `geometry` key, so
224|                //      the layer was empty and fitBounds threw "Bounds are not valid",
225|                //      leaving the draw toolbar permanently disabled.
226|                //   2. Even when a layer did load, MultiPolygon gave it THREE levels
227|                //      of nesting ([[ring]] -> [1] => [1] => [19] => LatLng).
228|                //      L.Edit.Poly only understands two ([ring]), so it enabled
229|                //      without error but rendered zero vertex handles and the
230|                //      boundary was not editable.
231|                // Normalise both: accept a bare geometry or a Feature, and unwrap
232|                // the single MultiPolygon to a plain Polygon so L.Edit.Poly works.
233|                var geometry = (data && data.geometry) ? data.geometry : data;
234|                if (geometry && geometry.type === 'MultiPolygon' && Array.isArray(geometry.coordinates)) {
235|                    geometry = {
236|                        type: 'Polygon',
237|                        coordinates: geometry.coordinates[0] || [],
238|                    };
239|                }
240|
241|                existingLayer = L.geoJSON({ type: 'Feature', properties: {}, geometry: geometry }, {
242|                    style: { color: '#f59e0b', weight: 3, opacity: 0.8, fillOpacity: 0.15 }
243|                }).addTo(unitMap);
244|
245|                // #702: the draw toolbar's edit/remove tools only operate on layers
246|                // inside `drawnItems`. The saved boundary was added straight to the
247|                // map, so it got no edit handles and the toolbar could not delete it —
248|                // only the bottom "حذف مرز" button worked.
249|                //
250|                // Add the INDIVIDUAL polygon layers (eachLayer), never the L.GeoJSON
251|                // group itself: updateGeojson() iterates getLayers() and only handles
252|                // L.Polygon instances.
253|                existingLayer.eachLayer(function (layer) {
254|                    drawnItems.addLayer(layer);
255|                });
256|
257|                unitMap.fitBounds(drawnItems.getBounds());
258|
259|                // #702: seed _mapGeojson from the loaded boundary. Without this,
260|                // _mapGeojson stayed undefined until the user drew something, and
261|                // saveMapBoundary() reads that as "nothing to save" and routed to
262|                // deleteBoundary() — so simply opening a unit with a boundary and
263|                // pressing ذخیره deleted it.
264|                updateGeojson();
265|            } catch (e) {
266|                console.error('Error loading existing boundary:', e);
267|            }
268|        }
269|
270|        var drawControl = new L.Control.Draw({
271|            edit: { featureGroup: drawnItems, remove: true },
272|            draw: {
273|                polygon: true,
274|                polyline: false,
275|                rectangle: false,
276|                circle: false,
277|                marker: false,
278|                circlemarker: false
279|            }
280|        });
281|        unitMap.addControl(drawControl);
282|
283|        unitMap.on('draw:created', function(event) {
284|            // #702: a unit has exactly one boundary, so a newly drawn polygon
285|            // replaces the previous one. The old layer now lives inside
286|            // `drawnItems`, so clearing the group replaces the previous
287|            // "remove existingLayer from map" logic.
288|            drawnItems.clearLayers();
289|
290|            var layer = event.layer;
291|            if (layer instanceof L.Rectangle) {
292|                layer = L.polygon(layer.getLatLngs()[0], layer.options);
293|            }
294|
295|            drawnItems.addLayer(layer);
296|            updateGeojson();
297|        });
298|
299|        unitMap.on('draw:edited', function() {
300|            updateGeojson();
301|        });
302|
303|        unitMap.on('draw:deleted', function() {
304|            updateGeojson();
305|        });
306|    }
307|
308|    function updateGeojson() {
309|        // Access drawnItems from the closure - use global reference
310|        var layers = window._drawnItems ? window._drawnItems.getLayers() : [];
311|        if (layers.length === 0) {
312|            window._mapGeojson = null;
313|            return;
314|        }
315|        var coords = [];
316|        layers.forEach(function(layer) {
317|            if (layer instanceof L.Polygon && !(layer instanceof L.Rectangle)) {
