    18	class SyncZabbixJob implements ShouldQueue
    19	{
    20	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
    21	
    22	    public int $timeout = 30;
    23	
    24	    public int $tries = 2;
    25	
    26	    public function handle(ZabbixService $zabbix): void
    27	    {
    28	        $outItemId = config('services.zabbix.out_item_id');
    29	        $inItemId = config('services.zabbix.in_item_id');
    30	
    31	        if (empty($outItemId) || empty($inItemId)) {
    32	            // The unconfigured-skip used to be a warning nobody read, so a
    33	            // misconfigured deployment stayed silently broken for weeks
    34	            // (#740). It now records a failed run like any other — the
    35	            // dashboard shows it and the streak can fire the admin alert.
    36	            Log::warning('SyncZabbixJob: Zabbix item IDs not configured. Skipping.');
    37	            $this->recordFailure('Zabbix item IDs not configured');
    38	
    39	            return;
    40	        }
    41	
    42	        $out = $zabbix->getInterfaceTraffic($outItemId);
    43	        $in = $zabbix->getInterfaceTraffic($inItemId);
    44	        $traffic = array_merge($out, $in);
    45	
    46	        Cache::put('zabbix_traffic_data', $traffic, now()->addMinutes(5));
    47	
    48	        Log::info('SyncZabbixJob: cached '.count($traffic).' traffic records.');
    49	
    50	        $this->recordSuccess();
    51	    }
    52	
    53	    /**
    54	     * Runs only after the queue gives up (tries exhausted), so one job
    55	     * failure produces exactly one failure row — retries do not inflate
    56	     * the consecutive-failure streak.
    57	     */
    58	    public function failed(Throwable $exception): void
    59	    {
    60	        Log::error('SyncZabbixJob failed: '.$exception->getMessage());
    61	
    62	        // Structured reporting alongside the log line: if the log channel
    63	        // itself is down, the exception handler still records it (#740).
    64	        report($exception);
    65	
    66	        $this->recordFailure($exception->getMessage());
    67	    }
    68	
    69	    private function recordSuccess(): void
    70	    {
    71	        (new ZabbixSyncLog([
    72	            'success' => true,
    73	            'consecutive_failures' => 0,
    74	            'ran_at' => now(),
    75	        ]))->save();
    76	    }
    77	
    78	    private function recordFailure(string $error): void
    79	    {
    80	        $previous = ZabbixSyncLog::query()->orderByDesc('id')->first();
    81	        $streak = ($previous !== null && ! $previous->success)
    82	            ? $previous->consecutive_failures + 1
    83	            : 1;
    84	
    85	        (new ZabbixSyncLog([
    86	            'success' => false,
    87	            'consecutive_failures' => $streak,
    88	            'error' => $error,
    89	            'ran_at' => now(),
    90	        ]))->save();
